/** The insert slots of every strip. */
export const INSERT_SLOTS = 4;

/**
 * One parameter of an effect. A value is a number in the parameter's own unit: for
 * `steps` the step's number from 0 (`steps` holds their ids), for `switch` 0 or 1.
 * `group`: the heading it sits under (the EQ's four bands).
 */
export interface EffectParam {
  readonly id: string;
  readonly group: string | null;
  readonly shape: "continuous" | "steps" | "switch";
  readonly steps: readonly string[];
  readonly unit: "hz" | "db" | "ms" | "s" | "percent" | "oct" | "ratio" | "none";
  readonly min: number;
  readonly max: number;
  readonly default: number;
}

